using System.Windows;using OncaPDV.Domain;
namespace OncaPDV.Desktop;
public partial class ProductWindow:Window{private readonly Product? _existing;public Product? Product{get;private set;}public ProductWindow(string? barcode=null,Product? existing=null){_existing=existing;InitializeComponent();if(existing is null){Barcode.Text=barcode??"";if(barcode is not null)Code.Text=barcode;return;}Code.Text=existing.InternalCode;Barcode.Text=existing.Barcode??"";ProductName.Text=existing.Name;Description.Text=existing.Description??"";Category.Text=existing.Category??"";Brand.Text=existing.Brand??"";Unit.Text=existing.Unit;Stock.Text=existing.Stock.ToString("N3");Stock.IsReadOnly=true;Cost.Text=existing.CostPrice.ToString("N2");Price.Text=existing.SalePrice.ToString("N2");Active.IsChecked=existing.Active;Title="Editar produto — estoque protegido";}private void Save_Click(object sender,RoutedEventArgs e){if(!decimal.TryParse(Cost.Text,out var cost)||!decimal.TryParse(Price.Text,out var price)||!decimal.TryParse(Stock.Text,out var stock)){MessageBox.Show("Custo, preço ou estoque inválido.");return;}Product=new(_existing?.Id??Guid.NewGuid(),Code.Text.Trim(),Null(Barcode.Text),ProductName.Text.Trim(),Null(Description.Text),Null(Category.Text),Null(Brand.Text),cost,price,_existing?.Stock??stock,_existing?.MinimumStock??0,Unit.Text.Trim(),_existing?.Supplier,_existing?.PhotoPath,Active.IsChecked==true,_existing?.PromotionalPrice,_existing?.PromotionStartsAt,_existing?.PromotionEndsAt);DialogResult=true;}private static string? Null(string value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();}
